// Стартовая точка для агентов Playwright, фича «היו כאן» (nearby): iPhone 13 Mini (WebKit), he-IL.
// Окно 1 — reg1 (32.0853, 34.7818), окно 2 — reg2 (32.0868, 34.7802), ~225 м. Геолокация только эмулированная.
// Состояние после сида не меняется (согласие не нажимается); тесты сами возвращают share_location=false, nearby_opt_in=false.
import { test, devices } from '@playwright/test';
import path from 'path';

const { defaultBrowserType: _b, ...iphone } = devices['iPhone 13 Mini'];
test.use({ browserName: 'webkit', ...iphone, locale: 'he-IL' });

test.describe('seed reg1-reg2 geo', () => {
  test('seed', async ({ browser, baseURL }) => {
    const open = async (role: 'reg1' | 'reg2', latitude: number, longitude: number) => {
      const ctx = await browser.newContext({
        ...iphone, baseURL, locale: 'he-IL',
        storageState: path.resolve(__dirname, '../../auth', `${role}.json`),
        geolocation: { latitude, longitude, accuracy: 10 }, permissions: ['geolocation'],
      });
      const page = await ctx.newPage();
      await page.goto('/map?tab=were-here');
      return page;
    };
    await open('reg1', 32.0853, 34.7818);
    await open('reg2', 32.0868, 34.7802);
  });
});
